const body = $input.item.json.body || $input.item.json;
const formName = body['form-name'] || body.form_name || 'gbp-audit';
const email = String(body.email || '').trim().toLowerCase();
const gbp = String(body.gbp_url || '').trim();
const website = String(body.website || '').trim();
const company = String(body.company || '').trim();
const zip = String(body.zip || '').trim();

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const gbpOk = !gbp || /google\.(com|co\.)|maps\.app\.goo\.gl|g\.page|business\.google/.test(gbp);
const websiteOk = !website || /^https?:\/\//i.test(website);

return {
  json: {
    ...body,
    form_name: formName,
    email,
    gbp_url: gbp,
    website,
    company,
    zip,
    received_at: body.received_at || new Date().toISOString(),
    valid: Boolean(emailOk && gbpOk && websiteOk && (formName === 'market-report' ? company && zip && website : gbp)),
    validation_errors: [
      !emailOk ? 'invalid_email' : null,
      formName === 'gbp-audit' && !gbp ? 'missing_gbp_url' : null,
      formName === 'gbp-audit' && gbp && !gbpOk ? 'gbp_url_not_google' : null,
      formName === 'market-report' && !company ? 'missing_company' : null,
      formName === 'market-report' && !zip ? 'missing_zip' : null,
      formName === 'market-report' && !websiteOk ? 'invalid_website' : null
    ].filter(Boolean)
  }
};
